                first is None or protected(first)
            ):
                return sqlite3.SQLITE_DENY
            return sqlite3.SQLITE_OK

        connection.set_authorizer(authorize)
        return connection

    sqlite3.connect = connect
    sqlite3.dbapi2.connect = connect

