    reserved = {
        scratch / (name + extension)
        for name in (requested, stem)
        for extension in (".json", ".log")
    }
    reserved.update(
        path.resolve()
        for path in scratch.iterdir()
        if path.suffix.casefold() in (".json", ".log")
    )

