        elif (
            argument.startswith("-")
            and not argument.startswith("--")
            and len(argument) > 2
        ):
            value = argument[2:].removeprefix("=")
        else:
            value = argument
        if not value.startswith("-") and comparable(Path(value)) in reserved_names:
